  bool IsCurrent(int ticket){return !IsDisposed&&ticket==sequence;}
  async Task LoadCity(IWeatherProvider provider,string city,WeatherPlace place,bool force=false){int ticket=Begin();View.UpdateState(true,network!=null&&network.CitySearchEnabled,"正在获取 "+city+" 的天气…");try{var live=provider as OpenMeteoWeatherProvider;var data=force&&live!=null?await live.ReadFreshAsync(city,operation.Token):await provider.ReadAsync(city,operation.Token);if(!IsCurrent(ticket))return;selected=place;displayed=data;View.Present(data,data.RefreshFailed?"刷新失败，暂时显示带时间标记的缓存。":data.EffectiveState(DateTimeOffset.UtcNow)=="unavailable"?WeatherCardControl.Status(data,DateTimeOffset.UtcNow)+"；稍后可重试。":network==null?"天气服务尚未配置；不会获取设备精确位置。":network.CitySearchEnabled?"搜索地区、查看预报；“设为常驻”才会修改外层卡片。":"天气已连接；城市搜索尚未获准联网。");}catch{if(IsCurrent(ticket))View.Present(new WeatherSnapshot{City=city,State="unavailable"},"天气获取失败，请稍后重试。");}finally{if(IsCurrent(ticket))View.UpdateState(false,network!=null&&network.CitySearchEnabled,View.Notice);}}
  [DllImport("user32.dll")]static extern bool ReleaseCapture();[DllImport("user32.dll")]static extern IntPtr SendMessage(IntPtr window,int message,IntPtr wParam,IntPtr lParam);
  protected override void OnSizeChanged(EventArgs e){base.OnSizeChanged(e);if(Width<2||Height<2)return;using(var path=GlassSurface.Path(new RectangleF(0,0,Width,Height),26)){var previous=Region;Region=new Region(path);if(previous!=null)previous.Dispose();}}
  protected override void Dispose(bool disposing){if(disposing&&operation!=null){operation.Cancel();operation.Dispose();operation=null;}base.Dispose(disposing);}
 }
